// 化学 题库（hx）：赤峰中考诊断。原创题，仿内蒙古中考风格。
ZK.banks.push({
  file: "hx",
  passages: [],
  items: [
    {"id":"hx.goucheng-L1-01","module":"hx.goucheng","level":1,"kp":"物质的构成微粒","prompt":"下列物质由离子构成的是","choices":["铜","水","氯化钠","金刚石"],"answer":2,"explain":"氯化钠由 Na^{+} 和 Cl^{-} 构成；铜是金属、金刚石是碳单质，都由原子直接构成；水由水分子构成。记住：金属、稀有气体、金刚石/石墨由原子构成，典型的盐由离子构成。"},
    {"id":"hx.goucheng-L1-02","module":"hx.goucheng","level":1,"kp":"分子的性质","prompt":"走进花园能闻到花香，用微粒观点解释，主要原因是","choices":["分子在不断运动","分子的质量和体积都很小","分子之间有间隔","分子在化学变化中可以再分"],"answer":0,"explain":"花香分子不断运动，扩散到空气中进入鼻腔，所以能闻到气味。其余三项虽然都是分子的性质，但解释不了“闻到气味”这一现象；而且闻香是物理变化，分子本身并没有改变。"},
    {"id":"hx.goucheng-L1-03","module":"hx.goucheng","level":1,"kp":"化学符号的意义","prompt":"下列化学用语中，表示“2个氢原子”的是","choices":["H_{2}","2H_{2}","2H^{+}","2H"],"answer":3,"explain":"元素符号前面的数字表示原子个数，所以 2H 表示2个氢原子。H_{2} 表示氢气或1个氢分子；2H_{2} 表示2个氢分子；2H^{+} 表示2个氢离子。"},
    {"id":"hx.goucheng-L1-04","module":"hx.goucheng","level":1,"kp":"物质的分类","prompt":"下列物质属于氧化物的是","choices":["氧气（O_{2}）","水（H_{2}O）","高锰酸钾（KMnO_{4}）","空气"],"answer":1,"explain":"氧化物是由两种元素组成、其中一种是氧元素的化合物，H_{2}O 符合。O_{2} 是单质；KMnO_{4} 含三种元素，虽含氧但不是氧化物；空气是混合物。"},
    {"id":"hx.goucheng-L1-05","module":"hx.goucheng","level":1,"kp":"元素周期表信息","stem":"硅元素在元素周期表中的信息如图所示。","prompt":"下列说法正确的是","choices":["硅原子的质子数为 28","硅的相对原子质量为 28.09","硅属于金属元素","硅的相对原子质量为 28.09 g"],"answer":1,"explain":"左上角 14 是原子序数（等于质子数），下方 28.09 是相对原子质量，单位是“1”，不写“g”。“硅”字是石字旁，属于非金属元素。","svg":"<svg viewBox=\"0 0 140 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"10\" y=\"10\" width=\"120\" height=\"120\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"20\" y=\"38\" font-size=\"18\" fill=\"currentColor\">14</text><text x=\"120\" y=\"38\" font-size=\"20\" text-anchor=\"end\" fill=\"currentColor\">Si</text><text x=\"70\" y=\"80\" font-size=\"22\" text-anchor=\"middle\" fill=\"currentColor\">硅</text><text x=\"70\" y=\"118\" font-size=\"18\" text-anchor=\"middle\" fill=\"currentColor\">28.09</text></svg>"},
    {"id":"hx.goucheng-L2-01","module":"hx.goucheng","level":2,"kp":"化合价与化学式","prompt":"“84”消毒液的有效成分是次氯酸钠（NaClO），其中氯元素的化合价为","choices":["-1","+3","+5","+1"],"answer":3,"explain":"化合物中各元素化合价代数和为零：Na 为 +1，O 为 -2，设 Cl 为 x，则 (+1)+x+(-2)=0，x=+1。-1 是 NaCl 中氯的化合价，不能照搬。"},
    {"id":"hx.goucheng-L2-02","module":"hx.goucheng","level":2,"kp":"原子结构示意图","stem":"镁原子的结构示意图如图所示。","prompt":"下列说法正确的是","choices":["在化学反应中镁原子易失去 2 个电子形成 Mg^{2+}","镁原子最外层有 8 个电子","镁属于非金属元素","镁原子核外有 2 个电子层"],"answer":0,"explain":"弧线表示电子层，镁原子有 3 个电子层，排布为 2、8、2，最外层只有 2 个电子，少于 4 个，易失去而形成带 2 个单位正电荷的 Mg^{2+}。镁是金属元素。","svg":"<svg viewBox=\"0 0 170 100\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"40\" cy=\"50\" r=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"40\" y=\"55\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">+12</text><path d=\"M70 28 Q84 50 70 72\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"83\" y=\"45\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">2</text><path d=\"M100 28 Q114 50 100 72\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"113\" y=\"45\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8</text><path d=\"M130 28 Q144 50 130 72\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"143\" y=\"45\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">2</text></svg>"},
    {"id":"hx.goucheng-L2-03","module":"hx.goucheng","level":2,"kp":"化学符号的意义","prompt":"下列关于符号中数字“2”的意义，说法正确的是","choices":["H_{2}O：水中含有 2 个氢原子","2N：2 个氮分子","Fe^{2+}：一个亚铁离子带 2 个单位的正电荷","2N：2 个氮元素"],"answer":2,"explain":"右上角数字表示一个离子所带电荷数。H_{2}O 中的 2 表示“一个水分子中”含 2 个氢原子，不能说“水中”；2N 表示 2 个氮原子；元素只讲种类不讲个数。"},
    {"id":"hx.goucheng-L2-04","module":"hx.goucheng","level":2,"kp":"化学式的意义与计算","prompt":"维生素 C 的化学式为 C_{6}H_{8}O_{6}。下列说法正确的是","choices":["维生素 C 由 6 个碳原子、8 个氢原子和 6 个氧原子构成","维生素 C 中氢元素的质量分数最大","碳、氢、氧三种元素的质量比为 9∶1∶12","维生素 C 的相对分子质量为 176 g"],"answer":2,"explain":"质量比 =(12×6)∶(1×8)∶(16×6)=72∶8∶96=9∶1∶12。维生素 C 由分子构成，“一个分子”才含 6、8、6 个原子；氧元素质量分数最大；相对分子质量单位是“1”。"},
    {"id":"hx.goucheng-L2-05","module":"hx.goucheng","level":2,"kp":"物质的分类","prompt":"下列物质中，属于单质的是","choices":["液氧","冰水混合物","洁净的空气","生铁"],"answer":0,"explain":"液氧就是液态的 O_{2}，只含一种元素的纯净物，是单质。冰水混合物只有 H_{2}O 一种物质，是化合物（不是混合物）；空气、生铁都是混合物。"},
    {"id":"hx.goucheng-L3-01","module":"hx.goucheng","level":3,"kp":"微观示意图分析","stem":"汽车尾气处理装置中，一氧化碳分子与一氧化氮分子在催化剂作用下反应，生成氮气分子和二氧化碳分子。","prompt":"关于该反应，下列说法正确的是","choices":["反应前后分子总数不变","该反应属于置换反应","生成氮气与二氧化碳的质量比为 7∶11","参加反应的一氧化碳与一氧化氮的分子个数比为 1∶1"],"answer":3,"explain":"方程式：2CO+2NO =催化剂= N_{2}+2CO_{2}。分子个数比 CO∶NO=2∶2=1∶1；分子数由 4 变为 3；反应物都是化合物，不是置换反应；质量比 28∶(2×44)=7∶22，7∶11 是忘乘计量数。"},
    {"id":"hx.goucheng-L3-02","module":"hx.goucheng","level":3,"kp":"原子结构示意图","stem":"某粒子的结构示意图如图所示（核内质子数为 x）。","prompt":"若该粒子是带 2 个单位负电荷的阴离子，则 x 为","choices":["10","8","12","11"],"answer":1,"explain":"核外共 2+8=10 个电子。阴离子的电子数比质子数多，带 2 个单位负电荷说明多 2 个电子，x=10-2=8（O^{2-}）。x=10 是原子（Ne），x=11、12 是阳离子。","svg":"<svg viewBox=\"0 0 140 100\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"40\" cy=\"50\" r=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"40\" y=\"55\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">+x</text><path d=\"M70 28 Q84 50 70 72\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"83\" y=\"45\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">2</text><path d=\"M100 28 Q114 50 100 72\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"113\" y=\"45\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8</text></svg>"},
    {"id":"hx.goucheng-L3-03","module":"hx.goucheng","level":3,"kp":"化合价与化学式","prompt":"已知某元素 R 在化合物中只有一种化合价，其氧化物的化学式为 R_{2}O_{3}。则它的氯化物的化学式为","choices":["RCl_{2}","RCl_{3}","R_{2}Cl_{3}","R_{3}Cl"],"answer":1,"explain":"由 R_{2}O_{3}：2x+3×(-2)=0，R 为 +3 价。氯化物中 Cl 为 -1 价，按“正前负后、交叉约简”得 RCl_{3}。R_{2}Cl_{3} 是照搬氧化物的原子个数。"},
    {"id":"hx.goucheng-L3-04","module":"hx.goucheng","level":3,"kp":"元素周期表信息","prompt":"下列关于元素周期表和原子结构的说法正确的是","choices":["同一族元素的原子，核外电子数相同","最外层电子数为 2 的原子一定是金属元素的原子","质子数相同的粒子一定属于同种元素","同一周期元素的原子，电子层数相同"],"answer":3,"explain":"周期数=电子层数，同周期电子层数相同。同族（主族）是最外层电子数相同，核外电子总数不同；He 最外层 2 个电子却是稀有气体；H_{2}O 与 Ne 都有 10 个质子，但不是同种元素（元素指质子数相同的“原子”）。"},
    {"id":"hx.goucheng-L3-05","module":"hx.goucheng","level":3,"kp":"微粒与元素概念","prompt":"下列说法正确的是","choices":["分子、原子、离子都可以直接构成物质","带电的粒子一定是离子","原子是最小的粒子，不可再分","由同种元素组成的物质一定是单质"],"answer":0,"explain":"水由分子、铁由原子、氯化钠由离子构成。质子、电子也带电但不是离子；原子只是“化学变化中”的最小粒子，原子本身由原子核和电子构成；O_{2} 与 O_{3} 混在一起只含一种元素，却是混合物。"},
    {"id":"hx.goucheng-L4-01","module":"hx.goucheng","level":4,"kp":"化学式的意义与计算","prompt":"某铁的氧化物中，铁元素与氧元素的质量比为 21∶8，则该氧化物的化学式为","choices":["FeO","Fe_{2}O_{3}","Fe_{3}O_{4}","无法确定"],"answer":2,"explain":"设化学式为 Fe_{x}O_{y}，56x∶16y=21∶8，解得 x∶y=(21/56)∶(8/16)=3∶4，即 Fe_{3}O_{4}。FeO 质量比 7∶2，Fe_{2}O_{3} 为 7∶3。"},
    {"id":"hx.goucheng-L4-02","module":"hx.goucheng","level":4,"kp":"化学式的意义与计算","prompt":"由 Na_{2}S、Na_{2}SO_{3}、Na_{2}SO_{4} 组成的混合物中，硫元素的质量分数为 32%，则氧元素的质量分数为","choices":["46%","24%","22%","54%"],"answer":2,"explain":"三种物质中 Na 与 S 的原子个数比都是 2∶1，质量比恒为 46∶32。S 占 32%，则 Na 占 46%，O 占 100%-32%-46%=22%。54% 是只减了钠（100%-46%），46% 是钠的含量。"},
    {"id":"hx.goucheng-L4-03","module":"hx.goucheng","level":4,"kp":"微观示意图分析","stem":"氨气（NH_{3}）在纯氧中可以燃烧，生成氮气和水，这一反应可用于开发新型零碳燃料。","prompt":"下列说法正确的是","choices":["生成的氮气与水的分子个数比为 1∶3","参加反应的氨气与氧气的质量比为 17∶32","反应前后氮元素的化合价不变","该反应属于化合反应"],"answer":0,"explain":"4NH_{3}+3O_{2} =点燃= 2N_{2}+6H_{2}O，N_{2}∶H_{2}O=2∶6=1∶3。质量比 (4×17)∶(3×32)=68∶96=17∶24；氮由 -3 价变为 0 价；生成物有两种，不是化合反应。"},
    {"id":"hx.goucheng-L4-04","module":"hx.goucheng","level":4,"kp":"离子与电荷守恒","prompt":"某溶液中只含有 K^{+}、Mg^{2+}、SO_{4}^{2-}、Cl^{-} 四种离子，其中 K^{+}、Mg^{2+}、Cl^{-} 的个数比为 4∶5∶8，则 SO_{4}^{2-} 与 Cl^{-} 的个数比为","choices":["3∶4","5∶8","1∶2","3∶8"],"answer":3,"explain":"溶液呈电中性：正电荷总数 4×1+5×2=14，负电荷 8×1+2n=14，得 n=3。所以 SO_{4}^{2-}∶Cl^{-}=3∶8。忘记 Mg^{2+}、SO_{4}^{2-} 各带 2 个电荷是常见错误。"},
    {"id":"hx.goucheng-L4-05","module":"hx.goucheng","level":4,"kp":"化学式的意义与计算","prompt":"某尿素[CO(NH_{2})_{2}]样品中氮元素的质量分数为 42%（杂质不含氮），则该样品中尿素的质量分数为","choices":["42%","90%","46.7%","95%"],"answer":1,"explain":"尿素中氮的质量分数 =28/60≈46.7%。样品中尿素的质量分数 =42%÷(28/60)=42%×60/28=90%。46.7% 是纯尿素的含氮量，42% 是样品含氮量，都不是所求。"},
    {"id":"hx.kongqi-L1-01","module":"hx.kongqi","level":1,"kp":"空气的组成","prompt":"空气中体积分数约为 21% 的气体是","choices":["氮气","氧气","稀有气体","二氧化碳"],"answer":1,"explain":"按体积计，空气中氮气约 78%、氧气约 21%、稀有气体约 0.94%、二氧化碳约 0.03%。注意是“体积分数”而不是质量分数。"},
    {"id":"hx.kongqi-L1-02","module":"hx.kongqi","level":1,"kp":"空气污染与防治","prompt":"下列物质中，目前不计入空气质量评价的主要污染物的是","choices":["二氧化硫","二氧化氮","PM2.5","二氧化碳"],"answer":3,"explain":"计入空气质量评价的主要污染物有 SO_{2}、CO、NO_{2}、O_{3}、PM10、PM2.5 等。二氧化碳是空气的成分之一，过多会加剧温室效应，但目前不计入空气污染物。"},
    {"id":"hx.kongqi-L1-03","module":"hx.kongqi","level":1,"kp":"氧气的化学性质","prompt":"硫在氧气中燃烧的现象是","choices":["发出明亮的蓝紫色火焰，生成有刺激性气味的气体","发出微弱的淡蓝色火焰，生成无色无味的气体","剧烈燃烧，火星四射，生成黑色固体","产生大量白烟，放出热量"],"answer":0,"explain":"硫在氧气中燃烧发出明亮的蓝紫色火焰，在空气中是淡蓝色火焰，生成的 SO_{2} 有刺激性气味。火星四射、生成黑色固体是铁丝燃烧；大量白烟是红磷燃烧。"},
    {"id":"hx.kongqi-L1-04","module":"hx.kongqi","level":1,"kp":"水的净化","prompt":"自来水厂净水过程中，活性炭的主要作用是","choices":["杀菌消毒","降低水的硬度","吸附水中的色素和异味","使悬浮杂质沉降"],"answer":2,"explain":"活性炭疏松多孔，具有吸附性，能吸附色素和异味。杀菌消毒用氯气等消毒剂；使悬浮杂质沉降用明矾；活性炭不能除去可溶性钙、镁化合物，不能软化硬水。"},
    {"id":"hx.kongqi-L1-05","module":"hx.kongqi","level":1,"kp":"燃烧条件与灭火","prompt":"炒菜时油锅着火，立即盖上锅盖即可灭火，其主要原理是","choices":["降低油的着火点","清除可燃物","隔绝氧气","使温度降到着火点以下"],"answer":2,"explain":"盖上锅盖使油与空气（氧气）隔绝，燃烧停止。着火点是物质本身的属性，一般不能“降低”；锅盖没有移走油，也不能明显降温。油锅着火不能用水浇。"},
    {"id":"hx.kongqi-L2-01","module":"hx.kongqi","level":2,"kp":"水的组成","prompt":"关于电解水实验，下列说法正确的是","choices":["负极与正极产生气体的体积比约为 2∶1","正极产生的气体能燃烧","该实验说明水是由氢气和氧气组成的","该实验说明水分子由 2 个氢原子和 1 个氧原子构成"],"answer":0,"explain":"“正氧负氢，氢二氧一”：负极 H_{2} 与正极 O_{2} 体积比约 2∶1，正极气体能使带火星木条复燃但本身不燃烧。实验说明水由氢、氧两种元素组成；仅凭该实验不能直接得出水分子中原子的个数（况且应说“一个水分子”）。"},
    {"id":"hx.kongqi-L2-02","module":"hx.kongqi","level":2,"kp":"二氧化碳的性质","prompt":"将二氧化碳通入紫色石蕊溶液中，溶液变红，原因是","choices":["二氧化碳本身显酸性","二氧化碳能溶于水","二氧化碳能使石蕊褪色","二氧化碳与水反应生成了碳酸"],"answer":3,"explain":"CO_{2}+H_{2}O=H_{2}CO_{3}，碳酸使紫色石蕊变红。干燥的 CO_{2} 不能使干燥的石蕊纸花变色，说明不是 CO_{2} 本身起作用；仅仅“溶于水”不会改变颜色。"},
    {"id":"hx.kongqi-L2-03","module":"hx.kongqi","level":2,"kp":"一氧化碳的性质","prompt":"下列关于 CO 和 CO_{2} 的说法正确的是","choices":["CO 和 CO_{2} 都能使澄清石灰水变浑浊","CO 有毒，能与血液中的血红蛋白结合","CO 和 CO_{2} 都能燃烧","可以用闻气味的方法鉴别 CO 和 CO_{2}"],"answer":1,"explain":"CO 易与血红蛋白结合，使人缺氧中毒。只有 CO_{2} 能使石灰水变浑浊；CO_{2} 不能燃烧也不支持燃烧；两者都是无色无味的气体，且 CO 有毒，不能闻。两者分子构成不同，所以性质差别大。"},
    {"id":"hx.kongqi-L2-04","module":"hx.kongqi","level":2,"kp":"水的净化","prompt":"生活中既能降低水的硬度，又能杀灭水中病菌的简便方法是","choices":["过滤","煮沸","加明矾","用活性炭吸附"],"answer":1,"explain":"煮沸时可溶性钙、镁化合物转化为水垢沉淀，硬度降低，高温还能杀菌。过滤只除去不溶性杂质；明矾只能使悬浮物沉降；活性炭只能吸附色素和异味。实验室常用蒸馏。"},
    {"id":"hx.kongqi-L2-05","module":"hx.kongqi","level":2,"kp":"碳单质","prompt":"金刚石很硬，石墨却很软，二者物理性质差异很大的原因是","choices":["组成元素不同","构成它们的原子种类不同","碳原子的大小不同","碳原子的排列方式不同"],"answer":3,"explain":"金刚石、石墨都是由碳元素组成的单质，都由碳原子构成，但碳原子排列方式不同，所以物理性质差异很大；而化学性质相似（如完全燃烧都生成 CO_{2}）。"},
    {"id":"hx.kongqi-L3-01","module":"hx.kongqi","level":3,"kp":"燃烧条件与灭火","stem":"在 80 ℃ 热水上方的铜片上放一小块白磷和一小块红磷，热水中也放一小块白磷。观察到只有铜片上的白磷燃烧。（白磷着火点约 40 ℃，红磷着火点约 240 ℃）","prompt":"下列说法正确的是","choices":["铜片上白磷燃烧、红磷不燃烧，说明燃烧需要温度达到着火点","铜片上白磷与水中白磷对比，说明燃烧需要可燃物","水中白磷不燃烧，是因为温度没有达到着火点","红磷不燃烧，是因为红磷不是可燃物"],"answer":0,"explain":"铜片上两者都与氧气接触、温度都是约 80 ℃，只有着火点低的白磷燃烧，说明要达到着火点。两处白磷对比说明燃烧需要氧气；水中白磷已达到着火点但缺氧；红磷是可燃物，只是温度不够。"},
    {"id":"hx.kongqi-L3-02","module":"hx.kongqi","level":3,"kp":"氧气的实验室制取","prompt":"用加热高锰酸钾的方法制取氧气并用排水法收集，下列操作错误的是","choices":["试管口略向下倾斜","试管口放一团棉花","实验结束时，先熄灭酒精灯，再把导管移出水面","导管口有连续均匀的气泡冒出时再开始收集"],"answer":2,"explain":"先熄灭酒精灯，试管内温度降低、压强减小，水会倒吸使热试管炸裂，应先移出导管再熄灯。其余操作正确：口略向下防冷凝水倒流；棉花防止粉末进入导管；开始冒出的是装置内空气。"},
    {"id":"hx.kongqi-L3-03","module":"hx.kongqi","level":3,"kp":"空气中氧气含量测定","prompt":"用红磷燃烧测定空气中氧气的含量，测得氧气的体积分数明显小于 1/5，可能的原因是","choices":["点燃红磷前没有夹紧弹簧夹","点燃的红磷伸入集气瓶过慢","红磷的量不足","所用红磷过量"],"answer":2,"explain":"红磷不足，氧气没被耗尽，进入的水偏少，结果偏小。未夹紧弹簧夹或伸入过慢，瓶内空气受热逸出，结果偏大。红磷过量是为了耗尽氧气，属于正确做法。"},
    {"id":"hx.kongqi-L3-04","module":"hx.kongqi","level":3,"kp":"燃料与能源","prompt":"下列关于燃料与能源的说法正确的是","choices":["煤、石油、天然气属于不可再生能源","氢气燃烧的产物会污染空气","天然气的主要成分是一氧化碳","化学反应中只有燃烧反应才放出热量"],"answer":0,"explain":"化石燃料短期内不能再生。氢气燃烧只生成水，是最清洁的燃料；天然气主要成分是甲烷（CH_{4}）；生石灰与水反应、中和反应等不是燃烧，也放热。"},
    {"id":"hx.kongqi-L3-05","module":"hx.kongqi","level":3,"kp":"二氧化碳的实验室制取","prompt":"实验室制取二氧化碳时，一般不用大理石与稀硫酸反应，原因是","choices":["稀硫酸不能与碳酸钙反应","反应太剧烈，不易控制","稀硫酸易挥发，使 CO_{2} 不纯","生成的硫酸钙微溶于水，覆盖在大理石表面，使反应难以持续"],"answer":3,"explain":"CaCO_{3}+H_{2}SO_{4}=CaSO_{4}+H_{2}O+CO_{2}↑，二者能反应，但 CaSO_{4} 微溶，覆盖在固体表面阻止反应继续。反应剧烈是碳酸钠粉末的问题；易挥发的是浓盐酸，稀硫酸不挥发。"},
    {"id":"hx.kongqi-L4-01","module":"hx.kongqi","level":4,"kp":"一氧化碳的性质","prompt":"用一氧化碳在高温下还原氧化铁，下列说法正确的是","choices":["玻璃管中固体由红棕色逐渐变为银白色","实验开始时先通一会儿 CO 再加热，目的是排尽装置内空气防止爆炸","尾气中的 CO 无毒，可以直接排放","该反应属于置换反应"],"answer":1,"explain":"CO 与空气混合加热可能爆炸，故先通 CO。Fe_{2}O_{3} 被还原为铁粉，铁粉是黑色而非银白色；CO 有毒，尾气要点燃或收集；反应物 CO 与 Fe_{2}O_{3} 都是化合物，不属于置换反应。"},
    {"id":"hx.kongqi-L4-02","module":"hx.kongqi","level":4,"kp":"可燃性气体的检验","stem":"某气体可能含有 H_{2}、CO、CH_{4} 中的一种或几种。点燃该气体，在火焰上方罩一个干冷烧杯，内壁出现水雾；再罩一个内壁涂有澄清石灰水的烧杯，石灰水变浑浊。","prompt":"该气体的组成不可能是","choices":["H_{2} 和 CO","只有 H_{2}","只有 CH_{4}","CO 和 CH_{4}"],"answer":1,"explain":"有水雾说明含氢元素，石灰水变浑浊说明含碳元素。只有 H_{2} 时燃烧不生成 CO_{2}，石灰水不会变浑浊，所以不可能。H_{2}+CO、CH_{4}、CO+CH_{4} 都同时含碳、氢元素，均有可能。"},
    {"id":"hx.kongqi-L4-03","module":"hx.kongqi","level":4,"kp":"碳的化学性质","prompt":"将 12 g 碳和 24 g 氧气放在密闭容器中，在一定条件下充分反应，最终容器中的气体是","choices":["只有 CO_{2}","只有 CO","CO_{2} 和剩余的 O_{2}","CO 和 CO_{2} 的混合物"],"answer":3,"explain":"12 g 碳完全生成 CO_{2} 需 O_{2} 32 g，完全生成 CO 需 O_{2} 16 g。现有 24 g 介于两者之间，氧气不足以全部生成 CO_{2}，又多于生成 CO 所需，所以得到 CO 和 CO_{2} 的混合物（各含 6 g 碳）。"},
    {"id":"hx.kongqi-L4-04","module":"hx.kongqi","level":4,"kp":"空气中氧气含量测定","stem":"用铜粉测定空气中氧气含量：硬质玻璃管内空气体积为 40 mL，与之相连的注射器内有 20 mL 空气。加热铜粉并反复推拉注射器，充分反应后冷却至室温，将气体全部推入注射器。","prompt":"此时注射器内气体体积约为","choices":["8 mL","12 mL","16 mL","4 mL"],"answer":0,"explain":"装置内空气共 40+20=60 mL，其中氧气约 60×1/5=12 mL 被铜消耗，剩余 48 mL；玻璃管占 40 mL，注射器读数约 48-40=8 mL。只算玻璃管中的氧气会得 12 mL，只算注射器中的会得 16 mL。"},
    {"id":"hx.kongqi-L4-05","module":"hx.kongqi","level":4,"kp":"燃烧条件与灭火","stem":"点燃的镁条伸入盛满二氧化碳的集气瓶中，镁条继续剧烈燃烧，生成白色固体氧化镁，瓶壁上附着黑色颗粒（碳）。","prompt":"由此得出的下列结论中，不正确的是","choices":["二氧化碳在一定条件下也能支持燃烧","镁等活泼金属着火不能用二氧化碳灭火","燃烧一定需要有氧气参加","该反应属于置换反应"],"answer":2,"explain":"2Mg+CO_{2} =点燃= 2MgO+C，单质+化合物生成新单质+新化合物，属于置换反应。镁能在 CO_{2} 中燃烧，说明燃烧不一定需要氧气，CO_{2} 灭火也有适用范围。"},
    {"id":"hx.jinshu-L1-01","module":"hx.jinshu","level":1,"kp":"金属的物理性质","prompt":"铜常用来制作导线，主要利用了铜的","choices":["导热性","延展性","导电性","金属光泽"],"answer":2,"explain":"导线用来输送电流，利用导电性。导热性用于炊具；延展性用于拉丝、压成薄片；金属光泽用于装饰。注意题目问的是“主要利用”。"},
    {"id":"hx.jinshu-L1-02","module":"hx.jinshu","level":1,"kp":"合金","prompt":"下列物质属于合金的是","choices":["不锈钢","氧化铁","金刚石","纯铁"],"answer":0,"explain":"合金是金属中熔合某些金属或非金属形成的具有金属特征的物质，不锈钢是铁中加入铬、镍等形成的合金。氧化铁是化合物；金刚石是非金属单质；纯铁是纯金属。"},
    {"id":"hx.jinshu-L1-03","module":"hx.jinshu","level":1,"kp":"金属锈蚀与防护","prompt":"铁制品生锈的条件是","choices":["铁只与水接触","铁只与氧气接触","铁与二氧化碳接触","铁与氧气和水同时接触"],"answer":3,"explain":"铁生锈是铁与空气中的氧气、水同时发生反应，缺少任何一个条件都不易生锈。所以防锈的思路是隔绝氧气或水，如刷漆、涂油、保持干燥。"},
    {"id":"hx.jinshu-L1-04","module":"hx.jinshu","level":1,"kp":"溶液的形成","prompt":"将下列物质分别放入足量水中，充分搅拌，能形成溶液的是","choices":["植物油","蔗糖","面粉","泥沙"],"answer":1,"explain":"蔗糖溶于水形成均一、稳定的混合物，是溶液。植物油与水形成乳浊液；面粉、泥沙形成悬浊液，静置后会分层或沉淀。"},
    {"id":"hx.jinshu-L1-05","module":"hx.jinshu","level":1,"kp":"金属活动性顺序","prompt":"下列金属中，活动性最强的是","choices":["锌","镁","铁","铜"],"answer":1,"explain":"活动性顺序：K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au。镁排在锌、铁、铜前面，活动性最强。"},
    {"id":"hx.jinshu-L2-01","module":"hx.jinshu","level":2,"kp":"金属的化学性质","prompt":"下列金属分别放入稀盐酸中，不能产生氢气的是","choices":["锌","铁","镁","铜"],"answer":3,"explain":"在金属活动性顺序中，排在氢前面的金属能置换出酸中的氢。铜排在氢后面，不能与稀盐酸反应；锌、铁、镁都排在氢前面。"},
    {"id":"hx.jinshu-L2-02","module":"hx.jinshu","level":2,"kp":"溶解时的吸放热","prompt":"下列物质溶于水后，溶液温度明显降低的是","choices":["硝酸铵","氢氧化钠","浓硫酸","氯化钠"],"answer":0,"explain":"硝酸铵溶解吸热，温度降低；氢氧化钠固体、浓硫酸溶解放热，温度升高；氯化钠溶解温度变化不明显。常用来判断吸放热或推断物质。"},
    {"id":"hx.jinshu-L2-03","module":"hx.jinshu","level":2,"kp":"饱和溶液与不饱和溶液","prompt":"硝酸钾的溶解度随温度升高而增大。要使接近饱和的硝酸钾溶液变为饱和溶液，下列方法不可行的是","choices":["加入硝酸钾固体","恒温蒸发水","升高温度","降低温度"],"answer":2,"explain":"对溶解度随温度升高而增大的物质，降温、加溶质、蒸发溶剂都可使其饱和；升温后溶解度变大，溶液更不饱和。若是氢氧化钙（溶解度随温度升高而减小），则应升温。"},
    {"id":"hx.jinshu-L2-04","module":"hx.jinshu","level":2,"kp":"金属锈蚀与防护","prompt":"下列说法正确的是","choices":["铝的金属活动性比铁弱","铁锈结构致密，能保护内部的铁","铝制品耐腐蚀，是因为其表面能形成一层致密的氧化铝薄膜","用钢丝球经常擦洗铝锅可延长使用寿命"],"answer":2,"explain":"铝比铁活泼，但在空气中表面生成致密的 Al_{2}O_{3} 薄膜，阻止内部继续被氧化。铁锈疏松多孔，不能保护内部的铁；用钢丝球擦洗会破坏铝表面的保护膜。"},
    {"id":"hx.jinshu-L2-05","module":"hx.jinshu","level":2,"kp":"金属的化学性质","prompt":"将洁净的铁丝放入硫酸铜溶液中，一段时间后观察到的现象是","choices":["铁丝表面有红色固体析出，溶液由蓝色逐渐变为浅绿色","铁丝表面有红色固体析出，溶液变为黄色","铁丝表面产生大量气泡","铁丝表面有银白色固体析出，溶液变为无色"],"answer":0,"explain":"Fe+CuSO_{4}=FeSO_{4}+Cu，生成红色的铜，溶液中 Cu^{2+}（蓝色）变为 Fe^{2+}（浅绿色）。置换反应中铁显 +2 价，不会生成黄色的 Fe^{3+} 溶液。"},
    {"id":"hx.jinshu-L2-06","module":"hx.jinshu","level":2,"kp":"金属活动性顺序","stem":"现有 X、Y、Z 三种金属：把 X、Y 分别放入稀硫酸中，X 表面产生气泡，Y 无明显现象；把 Y 放入 Z 的硝酸盐溶液中，Y 表面有 Z 析出。","prompt":"三种金属的活动性由强到弱的顺序是","choices":["Y＞X＞Z","Z＞Y＞X","X＞Z＞Y","X＞Y＞Z"],"answer":3,"explain":"X 能与酸反应而 Y 不能，说明 X＞H＞Y；Y 能置换出 Z，说明 Y＞Z。综合得 X＞Y＞Z。"},
    {"id":"hx.jinshu-L2-07","module":"hx.jinshu","level":2,"kp":"溶解度曲线","stem":"A、B、C 三种固体物质（均不含结晶水）的溶解度曲线如图所示。","prompt":"t₂ ℃ 时，三种物质的溶解度由大到小的顺序是","choices":["B＞A＞C","A＞B＞C","C＞B＞A","A＞C＞B"],"answer":1,"explain":"在 t₂ 处作竖线，交点从上到下依次是 A（60 g）、B（35 g）、C（10 g），所以 A＞B＞C。读溶解度曲线先找对温度，再比较交点高低。","svg":"<svg viewBox=\"0 0 340 270\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"50\" y1=\"230\" x2=\"320\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"50\" y1=\"230\" x2=\"50\" y2=\"25\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"10\" y=\"20\" font-size=\"12\" fill=\"currentColor\">溶解度/g</text><text x=\"300\" y=\"250\" font-size=\"12\" fill=\"currentColor\">温度/℃</text><text x=\"44\" y=\"246\" font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\">0</text><text x=\"170\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₁</text><text x=\"290\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₂</text><g stroke=\"currentColor\" stroke-dasharray=\"4 3\" stroke-width=\"1\" fill=\"none\"><line x1=\"170\" y1=\"230\" x2=\"170\" y2=\"140\"/><line x1=\"290\" y1=\"230\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"140\" x2=\"170\" y2=\"140\"/><line x1=\"50\" y1=\"50\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"170\" x2=\"170\" y2=\"170\"/><line x1=\"50\" y1=\"200\" x2=\"290\" y2=\"200\"/><line x1=\"170\" y1=\"125\" x2=\"290\" y2=\"125\"/></g><g font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\"><text x=\"46\" y=\"54\">60</text><text x=\"46\" y=\"144\">30</text><text x=\"46\" y=\"174\">20</text><text x=\"46\" y=\"204\">10</text></g><text x=\"176\" y=\"122\" font-size=\"12\" fill=\"currentColor\">35</text><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M50 200 C110 185 140 160 170 140 S260 80 290 50\"/><path d=\"M50 155 L170 140 L290 125\"/><path d=\"M50 146 C100 152 140 160 170 170 S250 190 290 200\"/></g><g font-size=\"14\" fill=\"currentColor\"><text x=\"296\" y=\"52\">A</text><text x=\"296\" y=\"129\">B</text><text x=\"296\" y=\"206\">C</text></g></svg>"},
    {"id":"hx.jinshu-L3-01","module":"hx.jinshu","level":3,"kp":"金属活动性顺序","prompt":"为验证 Fe、Cu、Ag 三种金属的活动性顺序，下列各组试剂不能达到目的的是","choices":["Fe、CuSO_{4} 溶液、Ag","Fe、Cu、Ag、稀盐酸","FeSO_{4} 溶液、Cu、AgNO_{3} 溶液","Fe、Cu、AgNO_{3} 溶液、稀盐酸"],"answer":1,"explain":"只用稀盐酸，Cu、Ag 都不反应，无法比较二者强弱。“两金夹一盐”（Fe、Ag 与 CuSO_{4}）和“两盐夹一金”（FeSO_{4}、AgNO_{3} 与 Cu）都可以；最后一组用盐酸比较 Fe＞Cu，再用 Cu 与 AgNO_{3} 比较 Cu＞Ag，也可以。"},
    {"id":"hx.jinshu-L3-02","module":"hx.jinshu","level":3,"kp":"溶解度曲线","stem":"A、B、C 三种固体物质（均不含结晶水）的溶解度曲线如图所示。","prompt":"下列说法正确的是","choices":["t₁ ℃ 时，A 的饱和溶液中溶质的质量分数为 30%","将 C 的饱和溶液从 t₁ ℃ 升温到 t₂ ℃，变为不饱和溶液","A 中混有少量 B，可用蒸发结晶的方法提纯 A","t₁ ℃ 时，A、B 两种物质饱和溶液的溶质质量分数相等"],"answer":3,"explain":"t₁ 时 A、B 溶解度相等（30 g），饱和溶液质量分数相等，为 30/130≈23.1%，不是 30%。C 的溶解度随温度升高而减小，升温会析出晶体，仍饱和。A 受温度影响大，应用降温结晶提纯。","svg":"<svg viewBox=\"0 0 340 270\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"50\" y1=\"230\" x2=\"320\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"50\" y1=\"230\" x2=\"50\" y2=\"25\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"10\" y=\"20\" font-size=\"12\" fill=\"currentColor\">溶解度/g</text><text x=\"300\" y=\"250\" font-size=\"12\" fill=\"currentColor\">温度/℃</text><text x=\"44\" y=\"246\" font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\">0</text><text x=\"170\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₁</text><text x=\"290\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₂</text><g stroke=\"currentColor\" stroke-dasharray=\"4 3\" stroke-width=\"1\" fill=\"none\"><line x1=\"170\" y1=\"230\" x2=\"170\" y2=\"140\"/><line x1=\"290\" y1=\"230\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"140\" x2=\"170\" y2=\"140\"/><line x1=\"50\" y1=\"50\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"170\" x2=\"170\" y2=\"170\"/><line x1=\"50\" y1=\"200\" x2=\"290\" y2=\"200\"/><line x1=\"170\" y1=\"125\" x2=\"290\" y2=\"125\"/></g><g font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\"><text x=\"46\" y=\"54\">60</text><text x=\"46\" y=\"144\">30</text><text x=\"46\" y=\"174\">20</text><text x=\"46\" y=\"204\">10</text></g><text x=\"176\" y=\"122\" font-size=\"12\" fill=\"currentColor\">35</text><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M50 200 C110 185 140 160 170 140 S260 80 290 50\"/><path d=\"M50 155 L170 140 L290 125\"/><path d=\"M50 146 C100 152 140 160 170 170 S250 190 290 200\"/></g><g font-size=\"14\" fill=\"currentColor\"><text x=\"296\" y=\"52\">A</text><text x=\"296\" y=\"129\">B</text><text x=\"296\" y=\"206\">C</text></g></svg>"},
    {"id":"hx.jinshu-L3-03","module":"hx.jinshu","level":3,"kp":"溶解度曲线","stem":"A、B、C 三种固体物质（均不含结晶水）的溶解度曲线如图所示。","prompt":"将 t₂ ℃ 时 A、B、C 的饱和溶液分别降温到 t₁ ℃，所得溶液的溶质质量分数大小关系是","choices":["A=B＞C","A＞B＞C","B＞A＞C","C＞A=B"],"answer":0,"explain":"A、B 降温后析出晶体，仍为 t₁ 时的饱和溶液，溶解度都是 30 g，质量分数相等。C 降温后溶解度增大，变为不饱和，溶质质量分数保持 t₂ 时的值（按 10 g 计算），最小。所以 A=B＞C。","svg":"<svg viewBox=\"0 0 340 270\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"50\" y1=\"230\" x2=\"320\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"50\" y1=\"230\" x2=\"50\" y2=\"25\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"10\" y=\"20\" font-size=\"12\" fill=\"currentColor\">溶解度/g</text><text x=\"300\" y=\"250\" font-size=\"12\" fill=\"currentColor\">温度/℃</text><text x=\"44\" y=\"246\" font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\">0</text><text x=\"170\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₁</text><text x=\"290\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₂</text><g stroke=\"currentColor\" stroke-dasharray=\"4 3\" stroke-width=\"1\" fill=\"none\"><line x1=\"170\" y1=\"230\" x2=\"170\" y2=\"140\"/><line x1=\"290\" y1=\"230\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"140\" x2=\"170\" y2=\"140\"/><line x1=\"50\" y1=\"50\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"170\" x2=\"170\" y2=\"170\"/><line x1=\"50\" y1=\"200\" x2=\"290\" y2=\"200\"/><line x1=\"170\" y1=\"125\" x2=\"290\" y2=\"125\"/></g><g font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\"><text x=\"46\" y=\"54\">60</text><text x=\"46\" y=\"144\">30</text><text x=\"46\" y=\"174\">20</text><text x=\"46\" y=\"204\">10</text></g><text x=\"176\" y=\"122\" font-size=\"12\" fill=\"currentColor\">35</text><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M50 200 C110 185 140 160 170 140 S260 80 290 50\"/><path d=\"M50 155 L170 140 L290 125\"/><path d=\"M50 146 C100 152 140 160 170 170 S250 190 290 200\"/></g><g font-size=\"14\" fill=\"currentColor\"><text x=\"296\" y=\"52\">A</text><text x=\"296\" y=\"129\">B</text><text x=\"296\" y=\"206\">C</text></g></svg>"},
    {"id":"hx.jinshu-L3-04","module":"hx.jinshu","level":3,"kp":"金属与酸反应的计算","prompt":"等质量的镁、锌、铁分别与足量的稀盐酸充分反应，生成氢气的质量由多到少的顺序是","choices":["锌＞铁＞镁","镁＞锌＞铁","镁＞铁＞锌","镁=铁=锌"],"answer":2,"explain":"三种金属在生成物中都显 +2 价，生成氢气质量 =金属质量×2/相对原子质量，相对原子质量越小生成越多：Mg(24)＜Fe(56)＜Zn(65)，故镁＞铁＞锌。“镁＞锌＞铁”是误用了活动性顺序，活动性只影响反应快慢。"},
    {"id":"hx.jinshu-L3-05","module":"hx.jinshu","level":3,"kp":"金属的化学性质","prompt":"黄铜（铜锌合金）外观与黄金相似，常被用来冒充黄金。下列鉴别方法不可行的是","choices":["在空气中灼烧","加入稀盐酸","观察颜色","放入硝酸银溶液中"],"answer":2,"explain":"两者颜色相近，观察颜色无法鉴别。灼烧时黄铜中的铜生成黑色 CuO，金不变；黄铜中的锌与稀盐酸反应产生气泡；黄铜能置换出银，表面有银白色固体。金都不反应。"},
    {"id":"hx.jinshu-L4-01","module":"hx.jinshu","level":4,"kp":"滤渣滤液成分判断","stem":"向 AgNO_{3} 和 Cu(NO_{3})_{2} 的混合溶液中加入一定量的锌粉，充分反应后过滤，向滤渣中滴加稀盐酸，无气泡产生。","prompt":"下列说法正确的是","choices":["滤渣中一定含有 Ag，可能含有 Cu","滤液中一定含有 Zn(NO_{3})_{2} 和 Cu(NO_{3})_{2}","滤渣中一定含有 Ag 和 Cu","滤液中一定不含 AgNO_{3}"],"answer":0,"explain":"锌先置换银，再置换铜。滤渣加盐酸无气泡，说明锌无剩余。锌一定先置换出 Ag；锌量不确定，Cu(NO_{3})_{2} 可能未反应、部分或全部反应，故 Cu 可能有，Cu(NO_{3})_{2} 不一定存在；锌很少时 AgNO_{3} 也可能有剩余。"},
    {"id":"hx.jinshu-L4-02","module":"hx.jinshu","level":4,"kp":"溶解度曲线","stem":"A、B、C 三种固体物质（均不含结晶水）的溶解度曲线如图所示。","prompt":"下列说法正确的是","choices":["t₂ ℃ 时，A 的饱和溶液中溶质与溶液的质量比为 3∶5","t₁ ℃ 时，将 15 g B 加入 50 g 水中，得到 65 g 不饱和溶液","C 的不饱和溶液降温，一定能变为饱和溶液","t₂ ℃ 时等质量的 A、B 饱和溶液降温到 t₁ ℃，析出晶体的质量 A＞B"],"answer":3,"explain":"A 的溶解度受温度影响大，等质量饱和溶液降温 A 析出更多。t₂ 时 A 溶质∶溶液=60∶160=3∶8；t₁ 时 50 g 水最多溶 15 g B，恰好饱和；C 的溶解度随降温增大，降温后更不饱和。","svg":"<svg viewBox=\"0 0 340 270\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"50\" y1=\"230\" x2=\"320\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"50\" y1=\"230\" x2=\"50\" y2=\"25\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"10\" y=\"20\" font-size=\"12\" fill=\"currentColor\">溶解度/g</text><text x=\"300\" y=\"250\" font-size=\"12\" fill=\"currentColor\">温度/℃</text><text x=\"44\" y=\"246\" font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\">0</text><text x=\"170\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₁</text><text x=\"290\" y=\"248\" font-size=\"13\" text-anchor=\"middle\" fill=\"currentColor\">t₂</text><g stroke=\"currentColor\" stroke-dasharray=\"4 3\" stroke-width=\"1\" fill=\"none\"><line x1=\"170\" y1=\"230\" x2=\"170\" y2=\"140\"/><line x1=\"290\" y1=\"230\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"140\" x2=\"170\" y2=\"140\"/><line x1=\"50\" y1=\"50\" x2=\"290\" y2=\"50\"/><line x1=\"50\" y1=\"170\" x2=\"170\" y2=\"170\"/><line x1=\"50\" y1=\"200\" x2=\"290\" y2=\"200\"/><line x1=\"170\" y1=\"125\" x2=\"290\" y2=\"125\"/></g><g font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\"><text x=\"46\" y=\"54\">60</text><text x=\"46\" y=\"144\">30</text><text x=\"46\" y=\"174\">20</text><text x=\"46\" y=\"204\">10</text></g><text x=\"176\" y=\"122\" font-size=\"12\" fill=\"currentColor\">35</text><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M50 200 C110 185 140 160 170 140 S260 80 290 50\"/><path d=\"M50 155 L170 140 L290 125\"/><path d=\"M50 146 C100 152 140 160 170 170 S250 190 290 200\"/></g><g font-size=\"14\" fill=\"currentColor\"><text x=\"296\" y=\"52\">A</text><text x=\"296\" y=\"129\">B</text><text x=\"296\" y=\"206\">C</text></g></svg>"},
    {"id":"hx.jinshu-L4-03","module":"hx.jinshu","level":4,"kp":"金属与酸反应的计算","prompt":"5.6 g 含一种杂质的铁粉与足量稀盐酸完全反应，生成 0.21 g 氢气，则铁粉中所含杂质可能是","choices":["锌","镁","铜","银"],"answer":1,"explain":"5.6 g 纯铁生成氢气 0.2 g（Fe~H_{2}，56∶2）。实际 0.21 g 偏多，杂质必须是等质量时产生氢气比铁多的金属。5.6 g 镁可生成约 0.47 g 氢气，符合；锌生成得比铁少，铜、银不产生氢气。"},
    {"id":"hx.jinshu-L4-04","module":"hx.jinshu","level":4,"kp":"溶解度与溶质质量分数","prompt":"20 ℃ 时 NaCl 的溶解度为 36 g。该温度下，向 100 g 溶质质量分数为 20% 的 NaCl 溶液中加入 10 g NaCl，充分搅拌后，所得溶液的溶质质量分数约为","choices":["27.3%","26.5%","30%","20%"],"answer":1,"explain":"原溶液含 NaCl 20 g、水 80 g，80 g 水最多溶 80×36/100=28.8 g，而 20+10=30 g＞28.8 g，固体没有全溶，溶液饱和，质量分数 =36/136≈26.5%。27.3% 是误认为 10 g 全部溶解（30/110）。"},
    {"id":"hx.jinshu-L4-05","module":"hx.jinshu","level":4,"kp":"滤渣滤液成分判断","stem":"向一定质量 AgNO_{3} 和 Cu(NO_{3})_{2} 的混合溶液中加入 m g 锌粉，充分反应后过滤，得到滤渣的质量仍为 m g。","prompt":"下列说法正确的是","choices":["滤渣中一定含有 Zn","滤液中一定含有 Cu(NO_{3})_{2}","滤渣中只有 Ag","滤液中一定不含 AgNO_{3}"],"answer":3,"explain":"Zn+2AgNO_{3}：65 份锌置换出 216 份银，固体质量增加；Zn+Cu(NO_{3})_{2}：65 份锌换 64 份铜，固体质量减少。总质量不变，说明两个反应都发生了，而锌先与 AgNO_{3} 反应，故 AgNO_{3} 已完全反应。Cu 一定有，Zn 和 Cu(NO_{3})_{2} 都不能确定。"},
    {"id":"hx.suanjian-L1-01","module":"hx.suanjian","level":1,"kp":"常见酸的性质","prompt":"浓盐酸敞口放置一段时间后，溶液质量减小，这是因为浓盐酸具有","choices":["挥发性","吸水性","腐蚀性","脱水性"],"answer":0,"explain":"浓盐酸易挥发出 HCl 气体，溶质减少，溶液质量和溶质质量分数都减小。吸水性、脱水性是浓硫酸的特性；浓硫酸敞口放置因吸水，溶液质量增大。"},
    {"id":"hx.suanjian-L1-02","module":"hx.suanjian","level":1,"kp":"物质的俗名","prompt":"氢氧化钠的俗称是","choices":["纯碱","熟石灰","烧碱","小苏打"],"answer":2,"explain":"氢氧化钠俗称烧碱、火碱、苛性钠。纯碱是碳酸钠（属于盐）；熟石灰是氢氧化钙；小苏打是碳酸氢钠。"},
    {"id":"hx.suanjian-L1-03","module":"hx.suanjian","level":1,"kp":"溶液酸碱性与pH","prompt":"下列生活中的物质，呈碱性的是","choices":["柠檬汁（pH≈2）","食盐水（pH=7）","肥皂水（pH≈10）","白醋（pH≈3）"],"answer":2,"explain":"常温下 pH＞7 的溶液呈碱性，pH=7 呈中性，pH＜7 呈酸性。肥皂水 pH≈10，呈碱性；柠檬汁、白醋呈酸性；食盐水呈中性。"},
    {"id":"hx.suanjian-L1-04","module":"hx.suanjian","level":1,"kp":"化肥","prompt":"下列化肥中，属于复合肥料的是","choices":["KNO_{3}","CO(NH_{2})_{2}","Ca_{3}(PO_{4})_{2}","K_{2}SO_{4}"],"answer":0,"explain":"复合肥料含氮、磷、钾中两种或两种以上营养元素，KNO_{3} 含 K 和 N。尿素只含氮（氮肥），磷酸钙只含磷（磷肥），硫酸钾只含钾（钾肥）。"},
    {"id":"hx.suanjian-L1-05","module":"hx.suanjian","level":1,"kp":"酸碱指示剂","prompt":"下列关于酸碱指示剂的说法正确的是","choices":["无色酚酞溶液遇稀盐酸变红","紫色石蕊溶液遇碱性溶液变红","紫色石蕊溶液遇酸性溶液变蓝","无色酚酞溶液遇氢氧化钠溶液变红"],"answer":3,"explain":"口诀：石蕊“酸红碱蓝”，酚酞“酸无碱红”。所以酚酞遇 NaOH 溶液变红，遇酸不变色；石蕊遇酸变红、遇碱变蓝。"},
    {"id":"hx.suanjian-L2-01","module":"hx.suanjian","level":2,"kp":"常见酸的性质","prompt":"稀释浓硫酸的正确操作是","choices":["将水沿器壁慢慢注入浓硫酸中，并不断搅拌","将浓硫酸沿器壁慢慢注入水中，并用玻璃棒不断搅拌","将浓硫酸迅速倒入水中","在量筒中直接稀释浓硫酸"],"answer":1,"explain":"浓硫酸溶于水放出大量热，且密度比水大。若把水倒入浓硫酸，水浮在上面沸腾，酸液飞溅。应“酸入水、沿器壁、慢慢倒、不断搅”；量筒不能用作反应或稀释容器。"},
    {"id":"hx.suanjian-L2-02","module":"hx.suanjian","level":2,"kp":"中和反应","prompt":"下列做法不属于中和反应应用的是","choices":["用熟石灰改良酸性土壤","用稀盐酸除去铁锈","用含氢氧化铝的药物治疗胃酸过多","被蚊虫叮咬后涂稀氨水减轻痛痒"],"answer":1,"explain":"中和反应是酸与碱作用生成盐和水。铁锈主要成分 Fe_{2}O_{3} 是金属氧化物，不是碱，所以除锈不是中和反应。熟石灰、氢氧化铝、氨水都是碱，分别与酸（蚁酸等）反应。"},
    {"id":"hx.suanjian-L2-03","module":"hx.suanjian","level":2,"kp":"复分解反应条件","prompt":"下列各组物质的溶液混合后，不能发生复分解反应的是","choices":["Na_{2}CO_{3} 和 HCl","BaCl_{2} 和 Na_{2}SO_{4}","NaOH 和 HCl","KNO_{3} 和 NaCl"],"answer":3,"explain":"复分解反应要有沉淀、气体或水生成。KNO_{3} 与 NaCl 交换成分后得到的 KCl、NaNO_{3} 都可溶，无沉淀、气体或水，不反应。其余分别生成 CO_{2}、BaSO_{4} 沉淀、水。"},
    {"id":"hx.suanjian-L2-04","module":"hx.suanjian","level":2,"kp":"氢氧化钠变质探究","prompt":"氢氧化钠固体敞口放置会变质。要检验其是否已经变质，下列方法可行的是","choices":["取样溶解，加入足量稀盐酸，观察是否产生气泡","取样溶解，滴加无色酚酞溶液，观察是否变红","取样加水溶解，观察是否放热","取样溶解，加入 NaCl 溶液，观察是否有沉淀"],"answer":0,"explain":"变质是 2NaOH+CO_{2}=Na_{2}CO_{3}+H_{2}O，检验 Na_{2}CO_{3} 即可，加足量盐酸有气泡说明已变质。Na_{2}CO_{3} 溶液也显碱性，酚酞变红不能说明问题；样品中只要还有 NaOH，溶于水就会放热，放热不能说明是否变质；NaCl 与两者都不反应。"},
    {"id":"hx.suanjian-L2-05","module":"hx.suanjian","level":2,"kp":"化肥","prompt":"铵态氮肥（如 NH_{4}Cl）不能与草木灰（主要成分 K_{2}CO_{3}，溶液显碱性）混合施用，原因是","choices":["两者反应生成沉淀，使土壤板结","混合后会使土壤酸化","两者反应会放出氨气，降低肥效","草木灰会吸附铵盐使其不能被吸收"],"answer":2,"explain":"铵盐与碱性物质混合会放出氨气（NH_{3}），使氮元素损失，降低肥效。这一性质也用于检验铵态氮肥：与熟石灰研磨，产生刺激性气味的气体。"},
    {"id":"hx.suanjian-L2-06","module":"hx.suanjian","level":2,"kp":"常见盐的性质","prompt":"下列关于碳酸钠（Na_{2}CO_{3}）的说法正确的是","choices":["碳酸钠属于碱","碳酸钠俗称小苏打","其水溶液能使无色酚酞溶液变红","碳酸钠不能与稀盐酸反应"],"answer":2,"explain":"碳酸钠溶液显碱性，能使酚酞变红，但它由金属离子和酸根离子构成，属于盐而不是碱。俗称纯碱、苏打；小苏打是 NaHCO_{3}。它与盐酸反应生成 CO_{2}。"},
    {"id":"hx.suanjian-L3-01","module":"hx.suanjian","level":3,"kp":"离子共存","prompt":"下列各组离子在 pH=1 的溶液中能大量共存，且形成无色溶液的是","choices":["Na^{+}、K^{+}、Cl^{-}、NO_{3}^{-}","Na^{+}、K^{+}、CO_{3}^{2-}、Cl^{-}","Cu^{2+}、Na^{+}、SO_{4}^{2-}、Cl^{-}","K^{+}、Ba^{2+}、OH^{-}、NO_{3}^{-}"],"answer":0,"explain":"pH=1 说明溶液中有大量 H^{+}。CO_{3}^{2-} 与 H^{+} 生成 CO_{2} 和水；OH^{-} 与 H^{+} 生成水；含 Cu^{2+} 的溶液呈蓝色，不符合“无色”。只有“Na^{+}、K^{+}、Cl^{-}、NO_{3}^{-}”这一组离子间互不反应且无色。"},
    {"id":"hx.suanjian-L3-02","module":"hx.suanjian","level":3,"kp":"物质的除杂","prompt":"下列除杂方法（括号内为杂质）正确的是","choices":["CO_{2}（CO）：点燃","CaO（CaCO_{3}）：加水溶解、过滤","KCl（MnO_{2}）：加水溶解、过滤、洗涤、干燥","NaCl 溶液（Na_{2}CO_{3}）：加入适量稀盐酸"],"answer":3,"explain":"Na_{2}CO_{3}+2HCl=2NaCl+H_{2}O+CO_{2}↑，不引入新杂质。大量 CO_{2} 中少量 CO 点不着；CaO 会与水反应，把主要物质除掉了；KCl 溶于水，过滤后洗涤干燥得到的是 MnO_{2}，应蒸发滤液。"},
    {"id":"hx.suanjian-L3-03","module":"hx.suanjian","level":3,"kp":"物质的检验与鉴别","prompt":"只用一种试剂，一次就能把稀盐酸、氯化钠溶液、氢氧化钠溶液区分开，这种试剂是","choices":["无色酚酞溶液","紫色石蕊溶液","稀硫酸","氯化钡溶液"],"answer":1,"explain":"紫色石蕊遇稀盐酸变红、遇 NaCl 溶液不变色（紫色）、遇 NaOH 溶液变蓝，三种现象不同。酚酞遇酸和中性溶液都不变色；稀硫酸、BaCl_{2} 溶液与三者混合都没有明显的不同现象。"},
    {"id":"hx.suanjian-L3-04","module":"hx.suanjian","level":3,"kp":"中和反应","stem":"用数字化传感器测得某次酸碱中和反应过程中溶液 pH 的变化如图所示。","prompt":"下列说法正确的是","choices":["该实验是将氢氧化钠溶液滴入稀盐酸中","c 点所示溶液中的溶质是 NaCl 和 HCl","a 点所示溶液中的溶质只有 NaOH","b 点之后的溶液滴加无色酚酞溶液会变红"],"answer":1,"explain":"起始 pH＞7，说明是把稀盐酸滴入 NaOH 溶液中。a 点已部分反应，溶质为 NaOH 和 NaCl；b 点 pH=7 恰好完全反应；c 点盐酸过量，溶质为 NaCl 和 HCl，溶液呈酸性，酚酞不变色。","svg":"<svg viewBox=\"0 0 320 240\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"40\" y1=\"200\" x2=\"305\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"200\" x2=\"40\" y2=\"15\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"12\" y=\"20\" font-size=\"13\" fill=\"currentColor\">pH</text><text x=\"34\" y=\"216\" font-size=\"12\" fill=\"currentColor\">0</text><text x=\"190\" y=\"225\" font-size=\"12\" fill=\"currentColor\">加入溶液的体积/mL</text><line x1=\"40\" y1=\"110\" x2=\"300\" y2=\"110\" stroke=\"currentColor\" stroke-dasharray=\"4 3\" stroke-width=\"1\"/><text x=\"32\" y=\"114\" font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\">7</text><path d=\"M40 33 C120 35 140 60 150 110 S180 185 290 187\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><g fill=\"currentColor\"><circle cx=\"121\" cy=\"53.5\" r=\"3\"/><circle cx=\"150\" cy=\"110\" r=\"3\"/><circle cx=\"182.5\" cy=\"166.5\" r=\"3\"/></g><g font-size=\"14\" fill=\"currentColor\"><text x=\"124\" y=\"46\">a</text><text x=\"156\" y=\"104\">b</text><text x=\"186\" y=\"160\">c</text></g></svg>"},
    {"id":"hx.suanjian-L3-05","module":"hx.suanjian","level":3,"kp":"复分解反应条件","prompt":"向 Ba(OH)_{2} 溶液中逐滴加入稀硫酸至过量，下列说法正确的是","choices":["整个过程中始终有沉淀生成","最终所得溶液呈碱性","恰好完全反应时，溶液中的溶质是 BaSO_{4}","溶液的导电能力先减弱至几乎为零，后又增强"],"answer":3,"explain":"Ba(OH)_{2}+H_{2}SO_{4}=BaSO_{4}↓+2H_{2}O，生成沉淀和水，溶液中离子越来越少，恰好反应时几乎不导电；继续加酸，H^{+}、SO_{4}^{2-} 增多，导电性增强。BaSO_{4} 是沉淀，不是溶质；硫酸过量，溶液最终呈酸性。"},
    {"id":"hx.suanjian-L4-01","module":"hx.suanjian","level":4,"kp":"物质推断","stem":"A～F 是初中化学常见物质。A 是红棕色固体，B 是有毒气体，A 与 B 在高温下反应生成 C 和 D，D 能使澄清石灰水变浑浊；C 放入蓝色溶液 E 中，生成红色固体 F 和浅绿色溶液。","prompt":"下列说法正确的是","choices":["C 与 E 的反应属于置换反应","A 与 B 的反应属于置换反应","E 溶液可以用铁制容器盛放","F 能与稀硫酸反应生成氢气"],"answer":0,"explain":"A 为 Fe_{2}O_{3}，B 为 CO，C 为 Fe，D 为 CO_{2}，E 为 CuSO_{4} 等铜盐溶液，F 为 Cu。Fe+CuSO_{4}=FeSO_{4}+Cu 是置换反应；CO 还原氧化铁反应物都是化合物，不是置换反应；铁会与 E 反应；铜在氢后不与稀硫酸反应。"},
    {"id":"hx.suanjian-L4-02","module":"hx.suanjian","level":4,"kp":"物质的检验与鉴别","stem":"某白色粉末可能含有 Na_{2}CO_{3}、Na_{2}SO_{4}、BaCl_{2}、NaCl 中的一种或几种。①取样加足量水，充分搅拌，得到白色沉淀和无色溶液；②过滤，向沉淀中加入足量稀硝酸，沉淀部分溶解，并产生气泡。","prompt":"关于该粉末的组成，下列判断正确的是","choices":["一定含有 Na_{2}CO_{3} 和 BaCl_{2}，可能含有 Na_{2}SO_{4}","四种物质一定都含有","一定含有 Na_{2}CO_{3}、Na_{2}SO_{4}、BaCl_{2}，可能含有 NaCl","一定含有 Na_{2}SO_{4} 和 BaCl_{2}，一定不含 Na_{2}CO_{3}"],"answer":2,"explain":"沉淀“部分溶解并有气泡”：溶解的是 BaCO_{3}（说明有 Na_{2}CO_{3}），不溶的是 BaSO_{4}（说明有 Na_{2}SO_{4}），生成沉淀必须有 BaCl_{2}。NaCl 对所有现象都没有影响，无法确定。"},
    {"id":"hx.suanjian-L4-03","module":"hx.suanjian","level":4,"kp":"物质的除杂","stem":"粗盐水中含有可溶性杂质 MgCl_{2}、CaCl_{2}、Na_{2}SO_{4}，所加试剂均过量。","prompt":"下列除杂操作顺序合理的是","choices":["Na_{2}CO_{3} 溶液→BaCl_{2} 溶液→NaOH 溶液→过滤→适量稀盐酸","BaCl_{2} 溶液→Na_{2}CO_{3} 溶液→NaOH 溶液→适量稀盐酸→过滤","BaCl_{2} 溶液→NaOH 溶液→Na_{2}CO_{3} 溶液→过滤→适量稀盐酸","NaOH 溶液→Na_{2}CO_{3} 溶液→BaCl_{2} 溶液→过滤→适量稀盐酸"],"answer":2,"explain":"关键：Na_{2}CO_{3} 必须在 BaCl_{2} 之后，才能同时除去 Ca^{2+} 和过量的 Ba^{2+}；盐酸必须在过滤之后，否则会溶解 Mg(OH)_{2}、CaCO_{3}、BaCO_{3} 沉淀。最后用盐酸除去过量的 NaOH 和 Na_{2}CO_{3}。"},
    {"id":"hx.suanjian-L4-04","module":"hx.suanjian","level":4,"kp":"反应先后与图像","prompt":"向盐酸和氯化钙的混合溶液中逐滴加入碳酸钠溶液至过量，下列说法正确的是","choices":["开始滴加时没有沉淀，只产生气泡","一开始滴加就产生白色沉淀","整个过程中溶液的 pH 始终小于 7","沉淀质量达到最大时，溶液中的溶质为 NaCl 和 HCl"],"answer":0,"explain":"即使先生成 CaCO_{3}，也会被盐酸溶解，所以 Na_{2}CO_{3} 先与 HCl 反应放出 CO_{2}，HCl 耗尽后才与 CaCl_{2} 生成沉淀。沉淀最多时溶质只有 NaCl；Na_{2}CO_{3} 过量后溶液 pH＞7。"},
    {"id":"hx.suanjian-L4-05","module":"hx.suanjian","level":4,"kp":"氢氧化钠变质探究","prompt":"要证明一瓶氢氧化钠溶液是“部分变质”，下列实验方案和结论正确的是","choices":["取样，加入过量 Ca(OH)_{2} 溶液，有白色沉淀；静置后向上层清液滴加酚酞，溶液变红","取样，加入足量稀盐酸，有气泡产生","取样，加入过量 CaCl_{2} 溶液，有白色沉淀；静置后向上层清液滴加酚酞，溶液不变色","取样，加入过量 CaCl_{2} 溶液，有白色沉淀；静置后向上层清液滴加酚酞，溶液变红"],"answer":3,"explain":"过量 CaCl_{2} 除尽 Na_{2}CO_{3}（生成 CaCO_{3} 沉淀，产物 NaCl 中性），清液使酚酞变红说明还有 NaOH，即部分变质。用 Ca(OH)_{2} 会生成 NaOH，干扰判断；只有气泡不能说明是“部分”；酚酞不变色说明已完全变质。"},
    {"id":"hx.fangcheng-L1-01","module":"hx.fangcheng","level":1,"kp":"质量守恒定律","prompt":"化学反应前后，下列各项一定不变的是","choices":["分子的种类","原子的种类、数目和质量","分子的数目","物质的种类"],"answer":1,"explain":"化学反应的实质是分子分成原子、原子重新组合成新分子，原子的种类、数目、质量都不变，所以质量守恒。分子种类、物质种类一定改变；分子数目可能改变。"},
    {"id":"hx.fangcheng-L1-02","module":"hx.fangcheng","level":1,"kp":"基本反应类型","prompt":"反应 2H_{2}O =通电= 2H_{2}↑+O_{2}↑ 属于","choices":["化合反应","分解反应","置换反应","复分解反应"],"answer":1,"explain":"一种反应物生成两种或两种以上生成物，“一变多”，属于分解反应。化合反应是“多变一”；置换反应是单质与化合物生成另一单质与化合物；复分解反应是两种化合物交换成分。"},
    {"id":"hx.fangcheng-L1-03","module":"hx.fangcheng","level":1,"kp":"化学方程式书写","prompt":"下列化学方程式书写正确的是","choices":["Mg+O_{2} =点燃= MgO_{2}","2Fe+6HCl=2FeCl_{3}+3H_{2}↑","H_{2}O_{2} =MnO₂= H_{2}↑+O_{2}↑","4P+5O_{2} =点燃= 2P_{2}O_{5}"],"answer":3,"explain":"氧化镁的化学式是 MgO，正确为 2Mg+O_{2} =点燃= 2MgO；铁与盐酸反应生成 FeCl_{2}，不是 FeCl_{3}；过氧化氢分解生成水和氧气：2H_{2}O_{2} =MnO₂= 2H_{2}O+O_{2}↑。"},
    {"id":"hx.fangcheng-L1-04","module":"hx.fangcheng","level":1,"kp":"质量守恒定律","prompt":"在反应 A+B=C+D 中，10 g A 与 5 g B 恰好完全反应，生成 8 g C，则生成 D 的质量为","choices":["7 g","15 g","3 g","13 g"],"answer":0,"explain":"参加反应的各物质质量总和等于生成的各物质质量总和：10+5=8+m(D)，m(D)=7 g。15 g 是反应物总质量，误当作 D 的质量。"},
    {"id":"hx.fangcheng-L1-05","module":"hx.fangcheng","level":1,"kp":"基本反应类型","prompt":"下列反应属于置换反应的是","choices":["CO+CuO =△= Cu+CO_{2}","CaCO_{3} =高温= CaO+CO_{2}↑","Zn+H_{2}SO_{4}=ZnSO_{4}+H_{2}↑","NaOH+HCl=NaCl+H_{2}O"],"answer":2,"explain":"置换反应：单质+化合物 → 新单质+新化合物，锌与稀硫酸反应符合。CO 是化合物，所以 CO 还原 CuO 不是置换反应；碳酸钙分解是分解反应；酸碱中和是复分解反应。"},
    {"id":"hx.fangcheng-L2-01","module":"hx.fangcheng","level":2,"kp":"化学式推断（守恒）","prompt":"某物质 X 燃烧的化学方程式为 2X+3O_{2} =点燃= 2CO_{2}+4H_{2}O，则 X 的化学式为","choices":["CH_{4}","C_{2}H_{6}O","CH_{4}O","CH_{2}O"],"answer":2,"explain":"反应前后原子种类和个数不变。右边：C 2 个、H 8 个、O 8 个；左边 3O_{2} 含 O 6 个。所以 2X 含 C 2、H 8、O 2，X 为 CH_{4}O（甲醇 CH_{3}OH）。忘了 X 前的计量数 2 容易出错。"},
    {"id":"hx.fangcheng-L2-02","module":"hx.fangcheng","level":2,"kp":"根据方程式计算","prompt":"加热 31.6 g 高锰酸钾至完全分解，可得到氧气的质量为","choices":["3.2 g","6.4 g","1.6 g","32 g"],"answer":0,"explain":"2KMnO_{4} =△= K_{2}MnO_{4}+MnO_{2}+O_{2}↑，316∶32=31.6 g∶x，x=3.2 g。若忘记 KMnO_{4} 前的计量数 2，用 158∶32 计算会得到 6.4 g。"},
    {"id":"hx.fangcheng-L2-03","module":"hx.fangcheng","level":2,"kp":"溶质质量分数计算","prompt":"将 50 g 溶质质量分数为 20% 的 NaCl 溶液稀释成 10% 的溶液，需要加水的质量为","choices":["100 g","25 g","40 g","50 g"],"answer":3,"explain":"稀释前后溶质质量不变：50×20%=10 g，稀释后溶液质量 =10÷10%=100 g，加水 100-50=50 g。100 g 是稀释后溶液的总质量，不是加水的质量。"},
    {"id":"hx.fangcheng-L2-04","module":"hx.fangcheng","level":2,"kp":"密闭容器数据分析","stem":"密闭容器内有甲、乙、丙、丁四种物质，一定条件下充分反应，测得反应前后各物质的质量如下：\n反应前/g：甲 20，乙 2，丙 15，丁 3\n反应后/g：甲 4，乙 2，丙 x，丁 27","prompt":"下列说法正确的是","choices":["x=15","该反应是化合反应","乙一定是该反应的催化剂","参加反应的甲与丙的质量比为 1∶2"],"answer":1,"explain":"总质量守恒：20+2+15+3=4+2+x+27，x=7。甲减少 16 g、丙减少 8 g（反应物），丁增加 24 g（生成物），甲+丙→丁，是化合反应，甲∶丙=16∶8=2∶1。乙质量不变，可能是催化剂，也可能是不参加反应的杂质。"},
    {"id":"hx.fangcheng-L2-05","module":"hx.fangcheng","level":2,"kp":"基本反应类型","prompt":"关于反应 C+2CuO =高温= 2Cu+CO_{2}↑，下列说法正确的是","choices":["氧化铜在反应中发生了氧化反应","该反应属于置换反应","反应前后各元素的化合价都不变","反应后固体的质量增加"],"answer":1,"explain":"单质碳与化合物 CuO 生成单质铜和化合物 CO_{2}，属于置换反应。CuO 失去氧，发生还原反应；碳由 0 价变为 +4 价，铜由 +2 价变为 0 价；生成的 CO_{2} 逸出，固体质量减少。"},
    {"id":"hx.fangcheng-L3-01","module":"hx.fangcheng","level":3,"kp":"根据方程式计算","prompt":"取 12.5 g 石灰石样品（杂质不溶于水，也不与盐酸反应），与足量稀盐酸充分反应，生成 4.4 g 二氧化碳。该样品中碳酸钙的质量分数为","choices":["35.2%","88%","40%","80%"],"answer":3,"explain":"CaCO_{3}+2HCl=CaCl_{2}+H_{2}O+CO_{2}↑，100∶44=x∶4.4 g，x=10 g，质量分数 =10÷12.5×100%=80%。35.2% 是用 CO_{2} 质量直接除以样品质量。"},
    {"id":"hx.fangcheng-L3-02","module":"hx.fangcheng","level":3,"kp":"溶质质量分数综合计算","prompt":"13 g 锌与 100 g 稀盐酸恰好完全反应，该稀盐酸中溶质的质量分数为","choices":["14.6%","7.3%","13%","12.9%"],"answer":0,"explain":"Zn+2HCl=ZnCl_{2}+H_{2}↑，65∶73=13 g∶x，x=14.6 g，质量分数 =14.6÷100×100%=14.6%。忘记 HCl 计量数 2（用 36.5）会得 7.3%；12.9% 是错误地除以 113 g。"},
    {"id":"hx.fangcheng-L3-03","module":"hx.fangcheng","level":3,"kp":"化学方程式配平","prompt":"乙烷（C_{2}H_{6}）完全燃烧生成二氧化碳和水。配平该化学方程式后（计量数为最简整数），O_{2} 前的化学计量数为","choices":["3.5","5","7","6"],"answer":2,"explain":"C_{2}H_{6}+O_{2}→2CO_{2}+3H_{2}O，右边氧原子 4+3=7 个，O_{2} 需 7/2，全部乘以 2：2C_{2}H_{6}+7O_{2} =点燃= 4CO_{2}+6H_{2}O。计量数要求最简整数，3.5 不行。"},
    {"id":"hx.fangcheng-L3-04","module":"hx.fangcheng","level":3,"kp":"溶质质量分数计算","prompt":"把 100 g 溶质质量分数为 98% 的浓硫酸稀释成 10% 的稀硫酸，需要加水的质量为","choices":["980 g","890 g","880 g","1080 g"],"answer":2,"explain":"溶质质量 =100×98%=98 g，稀释后溶液质量 =98÷10%=980 g，加水 =980-100=880 g。980 g 是稀释后溶液的质量，忘了减去原溶液质量。"},
    {"id":"hx.fangcheng-L3-05","module":"hx.fangcheng","level":3,"kp":"质量守恒定律","prompt":"在密闭容器中加热一定质量的铜粉，使其与容器内的氧气充分反应。下列关于反应过程的描述正确的是","choices":["容器内物质的总质量不变","容器内固体的质量不变","固体中铜元素的质量减小","容器内氧气的质量增大"],"answer":0,"explain":"密闭容器中无物质进出，总质量守恒。2Cu+O_{2} =△= 2CuO，固体结合了氧，质量增大；铜元素只是从 Cu 转入 CuO，质量不变；氧气被消耗，质量减小。"},
    {"id":"hx.fangcheng-L4-01","module":"hx.fangcheng","level":4,"kp":"元素守恒计算","prompt":"4.6 g 某纯净物在氧气中完全燃烧，生成 8.8 g CO_{2} 和 5.4 g H_{2}O。下列关于该物质的说法正确的是","choices":["只含碳、氢两种元素","一定含碳、氢元素，可能含氧元素","碳、氢原子个数比为 1∶2","含碳、氢、氧三种元素，碳、氢、氧原子个数比为 2∶6∶1"],"answer":3,"explain":"C：8.8×12/44=2.4 g；H：5.4×2/18=0.6 g；2.4+0.6=3.0 g＜4.6 g，所以含 O 1.6 g。原子个数比 C∶H∶O=(2.4/12)∶(0.6/1)∶(1.6/16)=0.2∶0.6∶0.1=2∶6∶1（如 C_{2}H_{6}O）。"},
    {"id":"hx.fangcheng-L4-02","module":"hx.fangcheng","level":4,"kp":"溶质质量分数综合计算","prompt":"称取 21.2 g Na_{2}CO_{3} 和 NaCl 的固体混合物，加入 100 g 稀盐酸，恰好完全反应，得到 116.8 g 溶液。所得溶液中 NaCl 的质量为","choices":["11.7 g","22.3 g","32.9 g","21.2 g"],"answer":1,"explain":"CO_{2}=21.2+100-116.8=4.4 g。Na_{2}CO_{3}+2HCl=2NaCl+H_{2}O+CO_{2}↑，得 Na_{2}CO_{3} 10.6 g、生成 NaCl 11.7 g；原混合物中 NaCl=21.2-10.6=10.6 g，共 22.3 g。只算生成的得 11.7 g；忘减 Na_{2}CO_{3} 得 32.9 g。"},
    {"id":"hx.fangcheng-L4-03","module":"hx.fangcheng","level":4,"kp":"根据方程式计算","prompt":"向 100 g CuSO_{4} 和 H_{2}SO_{4} 的混合溶液中逐滴加入溶质质量分数为 10% 的 NaOH 溶液，加入 40 g 时开始产生沉淀，加入 120 g 时沉淀质量不再增加。原混合溶液中 CuSO_{4} 的质量为","choices":["8 g","16 g","24 g","9.8 g"],"answer":1,"explain":"NaOH 先与 H_{2}SO_{4} 中和，40 g 后才与 CuSO_{4} 反应，消耗 NaOH 溶液 120-40=80 g，含 NaOH 8 g。2NaOH+CuSO_{4}=Cu(OH)_{2}↓+Na_{2}SO_{4}，80∶160=8 g∶x，x=16 g。用 120 g 计算得 24 g；9.8 g 是沉淀质量。"},
    {"id":"hx.fangcheng-L4-04","module":"hx.fangcheng","level":4,"kp":"元素守恒计算","prompt":"8 g 甲烷与 28.8 g 氧气在密闭容器中点燃，恰好完全反应，生成 CO、CO_{2} 和 18 g 水。生成 CO 的质量为","choices":["2.8 g","8.4 g","13.2 g","5.6 g"],"answer":3,"explain":"CO 与 CO_{2} 共 8+28.8-18=18.8 g，含碳 8×12/16=6 g。设 CO 为 x g，则 12x/28+12(18.8-x)/44=6，解得 x=5.6 g，CO_{2} 为 13.2 g。13.2 g 是 CO_{2} 的质量。"},
    {"id":"hx.fangcheng-L4-05","module":"hx.fangcheng","level":4,"kp":"溶质质量分数综合计算","prompt":"20 g 溶质质量分数为 20% 的 NaOH 溶液与一定量稀盐酸恰好完全反应，所得溶液质量为 40 g。所得溶液中溶质的质量分数约为","choices":["14.6%","10%","18.3%","29.3%"],"answer":0,"explain":"NaOH=20×20%=4 g，NaOH+HCl=NaCl+H_{2}O，40∶58.5=4 g∶x，x=5.85 g，质量分数 =5.85÷40×100%≈14.6%。10% 是把 NaOH 当溶质；18.3% 是稀盐酸的浓度（3.65/20）；29.3% 是错除以 20 g。"},
    {"id":"hx.shiyan-L1-01","module":"hx.shiyan","level":1,"kp":"基本实验操作","prompt":"下列实验操作正确的是","choices":["用燃着的酒精灯去点燃另一盏酒精灯","向试管中倾倒液体时，标签朝外","用灯帽盖灭酒精灯","用手直接拿取块状药品"],"answer":2,"explain":"酒精灯要用灯帽盖灭，不能用嘴吹；用燃着的酒精灯引燃另一盏易引起失火。倾倒液体时标签应朝向手心，防止残液腐蚀标签；不能用手接触药品，块状固体用镊子夹取。"},
    {"id":"hx.shiyan-L1-02","module":"hx.shiyan","level":1,"kp":"基本实验操作","prompt":"用量筒量取液体读数时，正确的方法是","choices":["俯视凹液面的最低处","仰视凹液面的最低处","视线与量筒内液体凹液面的最低处保持水平","视线与凹液面的最高处保持水平"],"answer":2,"explain":"读数时量筒放平，视线与凹液面最低处保持水平。俯视读数偏大（实际量取偏少），仰视读数偏小（实际量取偏多）。"},
    {"id":"hx.shiyan-L1-03","module":"hx.shiyan","level":1,"kp":"常见仪器","prompt":"下列仪器中，可以直接在酒精灯火焰上加热的是","choices":["试管","烧杯","量筒","集气瓶"],"answer":0,"explain":"可直接加热的有试管、蒸发皿、燃烧匙等；烧杯、锥形瓶加热时需垫陶土网；量筒、集气瓶不能加热。"},
    {"id":"hx.shiyan-L1-04","module":"hx.shiyan","level":1,"kp":"气体收集方法","prompt":"氧气可以用排水法收集，原因是","choices":["氧气密度比空气大","氧气能支持燃烧","氧气无色无味","氧气不易溶于水"],"answer":3,"explain":"排水法适用于不易溶于水（且不与水反应）的气体。“密度比空气大”是选择向上排空气法的依据；支持燃烧、无色无味与收集方法无关。"},
    {"id":"hx.shiyan-L1-05","module":"hx.shiyan","level":1,"kp":"过滤与蒸发","prompt":"过滤操作需要用到的一组玻璃仪器是","choices":["漏斗、量筒、玻璃棒","漏斗、烧杯、玻璃棒","漏斗、烧杯、酒精灯","试管、烧杯、玻璃棒"],"answer":1,"explain":"过滤需要铁架台（带铁圈）、漏斗、烧杯、玻璃棒（引流），其中玻璃仪器是漏斗、烧杯、玻璃棒。量筒用于量取液体；酒精灯用于加热，过滤都用不到。"},
    {"id":"hx.shiyan-L2-01","module":"hx.shiyan","level":2,"kp":"气体制取装置选择","prompt":"实验室常用加热氯化铵和熟石灰固体混合物的方法制取氨气。氨气极易溶于水，密度比空气小。应选用的发生装置和收集方法是","choices":["固液常温型装置，向下排空气法","固体加热型装置，向下排空气法","固体加热型装置，排水法","固体加热型装置，向上排空气法"],"answer":1,"explain":"发生装置看反应物状态和条件：固体+加热，选固体加热型。收集方法看气体性质：氨气极易溶于水，不能用排水法；密度比空气小，用向下排空气法。"},
    {"id":"hx.shiyan-L2-02","module":"hx.shiyan","level":2,"kp":"过滤与蒸发","prompt":"过滤后发现滤液仍然浑浊，可能的原因是","choices":["滤纸没有紧贴漏斗内壁","漏斗下端没有紧靠烧杯内壁","过滤速度太慢","滤纸破损"],"answer":3,"explain":"滤纸破损或液面高于滤纸边缘，浑浊液未经过滤直接流下，滤液仍浑浊；盛滤液的烧杯不干净也会如此。滤纸没紧贴会使过滤变慢；漏斗下端没靠烧杯内壁会使滤液溅出。"},
    {"id":"hx.shiyan-L2-03","module":"hx.shiyan","level":2,"kp":"配制溶液误差分析","prompt":"配制溶质质量分数为 6% 的氯化钠溶液，下列操作会导致所配溶液溶质质量分数偏小的是","choices":["用量筒量取水时仰视读数","用量筒量取水时俯视读数","配好的溶液装瓶时洒出少量","称量时所用砝码生锈"],"answer":0,"explain":"仰视读数，实际量取的水偏多，质量分数偏小；俯视则水偏少，结果偏大。砝码生锈质量变大，称得氯化钠偏多，结果偏大。溶液是均一的，配好后洒出不影响质量分数。"},
    {"id":"hx.shiyan-L2-04","module":"hx.shiyan","level":2,"kp":"气体制取装置选择","prompt":"实验室用大理石和稀盐酸制取二氧化碳，应选用的发生装置和收集方法是","choices":["固体加热型装置，向上排空气法","固液常温型装置，向下排空气法","固液常温型装置，向上排空气法","固体加热型装置，向下排空气法"],"answer":2,"explain":"大理石是固体，稀盐酸是液体，反应不需加热，选固液常温型装置。CO_{2} 能溶于水且与水反应，一般不用排水法；密度比空气大，用向上排空气法。"},
    {"id":"hx.shiyan-L2-05","module":"hx.shiyan","level":2,"kp":"过滤与蒸发","prompt":"进行“粗盐中难溶性杂质的去除”实验时，关于蒸发操作说法正确的是","choices":["要将滤液完全蒸干后再停止加热","蒸发时不需要用玻璃棒搅拌","当蒸发皿中出现较多固体时，停止加热，用余热蒸干","蒸发皿必须垫上陶土网加热"],"answer":2,"explain":"出现较多固体时停止加热，利用余热蒸干，防止固体飞溅。蒸发时要用玻璃棒不断搅拌，防止局部温度过高造成液滴飞溅；蒸发皿可以直接加热。"},
    {"id":"hx.shiyan-L3-01","module":"hx.shiyan","level":3,"kp":"控制变量","stem":"探究铁生锈的条件：①铁钉一半浸在蒸馏水中，一半露在空气中；②铁钉浸没在煮沸后迅速冷却的蒸馏水中，水面用植物油封住；③铁钉放在装有干燥剂的密闭试管中。一周后只有①中铁钉生锈。","prompt":"下列说法正确的是","choices":["对比①②，说明铁生锈需要氧气","对比②③，说明铁生锈需要水","对比①③，说明铁生锈需要氧气","该实验说明铁生锈只需要水"],"answer":0,"explain":"①②唯一的区别是有无氧气（②中水煮沸除氧、油封隔绝空气），说明需要氧气；①③区别是有无水，说明需要水。②③都没生锈，对比得不出结论。所以铁生锈需要氧气和水同时存在。"},
    {"id":"hx.shiyan-L3-02","module":"hx.shiyan","level":3,"kp":"实验方案设计与评价","prompt":"下列实验方案能达到实验目的的是","choices":["除去 CO_{2} 中混有的 HCl：通过足量 NaOH 溶液","检验某气体是 CO_{2}：伸入燃着的木条，观察是否熄灭","比较锌和铜的金属活动性：观察二者颜色","鉴别硬水和软水：加入肥皂水，振荡，观察泡沫多少"],"answer":3,"explain":"加肥皂水，泡沫多、浮渣少的是软水。NaOH 会把 CO_{2} 一起吸收，应用饱和 NaHCO_{3} 溶液；使燃着木条熄灭的还可能是 N_{2} 等，检验 CO_{2} 要用澄清石灰水；颜色与活动性无关。"},
    {"id":"hx.shiyan-L3-03","module":"hx.shiyan","level":3,"kp":"气体制取装置选择","prompt":"用过氧化氢溶液和二氧化锰制取氧气时，用分液漏斗代替长颈漏斗，主要优点是","choices":["可以使反应随时发生、随时停止","可以控制反应的速率","可以增加生成氧气的总质量","不需要检查装置的气密性"],"answer":1,"explain":"分液漏斗有活塞，能控制液体滴加速度，从而控制反应速率。“随时发生、随时停止”需要带多孔隔板和弹簧夹的装置，且二氧化锰是粉末，不适用；氧气总量由过氧化氢的量决定；任何制气装置都要检查气密性。"},
    {"id":"hx.shiyan-L3-04","module":"hx.shiyan","level":3,"kp":"多功能瓶的使用","stem":"如图所示的装置中装满水，a 管伸到瓶底附近，b 管刚刚伸过瓶塞。","prompt":"用该装置以排水法收集氧气，氧气应从哪端通入","choices":["a 端（长管）","b 端（短管）","a、b 两端都可以","先从 a 端、再从 b 端"],"answer":1,"explain":"排水法收集时气体密度比水小，聚集在瓶上部，应从短管 b 进入，把水从长管 a 压出。若从长管通入，气体会从短管直接逸出。口诀：排水集气“短进长出”。","svg":"<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"55\" y=\"45\" width=\"90\" height=\"140\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><rect x=\"57\" y=\"50\" width=\"86\" height=\"133\" rx=\"8\" fill=\"currentColor\" fill-opacity=\"0.12\"/><rect x=\"65\" y=\"35\" width=\"70\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"85\" y1=\"20\" x2=\"85\" y2=\"170\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"115\" y1=\"20\" x2=\"115\" y2=\"65\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"85\" y=\"14\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">a</text><text x=\"115\" y=\"14\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">b</text><text x=\"125\" y=\"130\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">水</text></svg>"},
    {"id":"hx.shiyan-L3-05","module":"hx.shiyan","level":3,"kp":"实验探究","prompt":"CO_{2} 与 NaOH 溶液反应没有明显现象。下列方案中，能证明二者确实发生了反应的是","choices":["向反应后的溶液中滴加无色酚酞溶液，溶液变红","观察到通入 CO_{2} 后溶液无明显变化","向反应后的溶液中继续通入 CO_{2}","向反应后的溶液中加入足量稀盐酸，产生气泡"],"answer":3,"explain":"证明有新物质 Na_{2}CO_{3} 生成即可：加足量稀盐酸产生气泡（原溶液中的 NaOH 与盐酸反应无气体）。NaOH 和 Na_{2}CO_{3} 溶液都能使酚酞变红；无明显现象正是需要证明的问题；继续通 CO_{2} 也看不到现象。"},
    {"id":"hx.shiyan-L4-01","module":"hx.shiyan","level":4,"kp":"控制变量","stem":"两个相同的软塑料瓶中都充满 CO_{2}，分别注入等体积的水和 NaOH 溶液，迅速拧紧瓶盖振荡，发现注入 NaOH 溶液的瓶子变瘪程度明显更大。","prompt":"设计注入水的那一组实验，目的是","choices":["排除 CO_{2} 溶于水（及与水反应）对实验结果的干扰","证明 CO_{2} 能与水反应生成碳酸","证明 NaOH 溶于水放出热量","证明 CO_{2} 的密度比空气大"],"answer":0,"explain":"CO_{2} 能溶于水，只用 NaOH 溶液一组，瓶子变瘪可能只是因为溶于水。设置等体积水的对照组，若 NaOH 组更瘪，才能说明 CO_{2} 与 NaOH 发生了反应。水组本身看不出生成了碳酸。"},
    {"id":"hx.shiyan-L4-02","module":"hx.shiyan","level":4,"kp":"反应后溶液成分探究","stem":"将稀盐酸加入氢氧化钙溶液中，没有明显现象。同学们对反应后溶液中溶质的成分提出猜想：①CaCl_{2}；②CaCl_{2} 和 HCl；③CaCl_{2} 和 Ca(OH)_{2}；④CaCl_{2}、HCl 和 Ca(OH)_{2}。","prompt":"下列分析正确的是","choices":["取样滴加无色酚酞溶液，不变色，则猜想①成立","取样滴加 AgNO_{3} 溶液，产生白色沉淀，说明溶液中含有 HCl","猜想④不合理；取样逐滴加入 Na_{2}CO_{3} 溶液，若先产生气泡后产生沉淀，则猜想②成立","猜想③不合理，因为 Ca(OH)_{2} 与 CaCl_{2} 不能共存"],"answer":2,"explain":"HCl 与 Ca(OH)_{2} 会反应，不能共存，猜想④不合理。有 HCl 时 Na_{2}CO_{3} 先与酸反应放气，再与 CaCl_{2} 生成沉淀。酚酞在酸性和中性溶液中都不变色，无法区分①②；CaCl_{2} 也含 Cl^{-}，会与 AgNO_{3} 生成沉淀。"},
    {"id":"hx.shiyan-L4-03","module":"hx.shiyan","level":4,"kp":"气体的检验与除杂","prompt":"要检验某混合气体中同时含有水蒸气、CO_{2} 和 CO，气体依次通过下列试剂或装置的顺序合理的是","choices":["澄清石灰水→无水硫酸铜→NaOH 溶液→灼热的氧化铜→澄清石灰水","无水硫酸铜→NaOH 溶液→澄清石灰水→灼热的氧化铜→澄清石灰水","无水硫酸铜→澄清石灰水→NaOH 溶液→灼热的氧化铜→澄清石灰水","无水硫酸铜→澄清石灰水→灼热的氧化铜→NaOH 溶液→澄清石灰水"],"answer":2,"explain":"先用无水硫酸铜检验水（若先过溶液会带出水蒸气干扰），再用石灰水检验 CO_{2}，然后用 NaOH 溶液除尽 CO_{2}，再通过灼热 CuO，石灰水变浑浊才能证明有 CO。先过 NaOH 会除掉原有 CO_{2}；CuO 后接 NaOH 会吸收生成的 CO_{2}。"},
    {"id":"hx.shiyan-L4-04","module":"hx.shiyan","level":4,"kp":"控制变量","stem":"探究影响过氧化氢分解速率的因素，设计实验如下（H_{2}O_{2} 溶液均为 10 mL）：\n①5% H_{2}O_{2}，20 ℃，不加催化剂\n②5% H_{2}O_{2}，20 ℃，加 0.5 g MnO_{2}\n③10% H_{2}O_{2}，20 ℃，加 0.5 g MnO_{2}\n④5% H_{2}O_{2}，40 ℃，不加催化剂","prompt":"下列说法错误的是","choices":["对比①③，可以探究浓度对反应速率的影响","对比①②，可以探究催化剂对反应速率的影响","对比②③，可以探究浓度对反应速率的影响","对比①④，可以探究温度对反应速率的影响"],"answer":0,"explain":"控制变量要求只改变一个因素。①③中浓度和有无催化剂两个因素都不同，无法得出结论。①②只差催化剂，②③只差浓度，①④只差温度，都是合理的对比。"},
    {"id":"hx.shiyan-L4-05","module":"hx.shiyan","level":4,"kp":"实验方案设计与评价","stem":"测定某碳酸钠样品的纯度：将样品与足量稀盐酸反应，生成的气体直接通入盛有足量 NaOH 溶液的装置中，根据该装置增加的质量计算 CO_{2} 质量，进而求出 Na_{2}CO_{3} 的质量。","prompt":"测得的结果偏大，可能的原因是","choices":["反应后装置中残留部分 CO_{2}，没有被吸收","样品没有完全反应","所用 NaOH 溶液的浓度偏大","生成的气体中混有水蒸气和挥发出的 HCl，也被 NaOH 溶液吸收"],"answer":3,"explain":"盐酸挥发出的 HCl 和带出的水蒸气被 NaOH 溶液吸收，使“CO_{2} 质量”偏大，结果偏大，应先干燥、除 HCl。残留 CO_{2} 和样品未反应完都会使结果偏小；NaOH 足量时浓度大小不影响。"},
  ],
});
